    function _calIsoOf(d) { const x = (d instanceof Date) ? d : new Date(d); return _calIsoFmt(x.getFullYear(), x.getMonth() + 1, x.getDate()); }
    function _calIsoFirstOfMonth(d) { const x = (d instanceof Date) ? d : new Date(d); return _calIsoFmt(x.getFullYear(), x.getMonth() + 1, 1); }
    function _calParseIso(iso) { const [Y,M,D] = String(iso).split('-').map(Number); return new Date(Y, (M||1) - 1, D || 1); }
    function _calIsoMondayOf(d) { const x = (d instanceof Date) ? new Date(d.getFullYear(), d.getMonth(), d.getDate()) : _calParseIso(d); const dow = (x.getDay() + 6) % 7; x.setDate(x.getDate() - dow); return _calIsoOf(x); }
